  ('organic', 'Органика', 'Органикалық қалдық', 'organic', true, false, 'Пищевые отходы без пакета', 'Тамақ қалдықтары пакетсіз', 'Компост, биогумус, биогаз', 'Компост, биогумус, биогаз', 'leaf', '#84CC16', 9),
